from datetime import datetime, timedelta, timezone
from azure.identity import DefaultAzureCredential
from azure.monitor.query import MetricsQueryClient, MetricAggregationType


def aggregate_metric_stats(payload, config=None):
    config = config or {}
    start = datetime.fromtimestamp(payload['start_time'], tz=timezone.utc)
    end = datetime.fromtimestamp(payload['end_time'], tz=timezone.utc)
    with DefaultAzureCredential() as credential:
        with MetricsQueryClient(credential) as client:
            result = client.query_resource(config['resource_id'], metric_names=[payload['metric']],
                                           timespan=(start, end),
                                           granularity=timedelta(seconds=config.get('period_seconds', 60)),
                                           aggregations=[MetricAggregationType.MIN, MetricAggregationType.MAX,
                                                         MetricAggregationType.AVERAGE, MetricAggregationType.COUNT,
                                                         MetricAggregationType.TOTAL])

    stats = {}
    for metric in result.metrics:
        for series in metric.timeseries:
            for point in series.data:
                if point.average is not None:
                    stats.setdefault('average', []).append(float(point.average))
                if point.minimum is not None:
                    stats.setdefault('minimum', []).append(float(point.minimum))
                if point.maximum is not None:
                    stats.setdefault('maximum', []).append(float(point.maximum))
                if point.count is not None:
                    stats.setdefault('count', []).append(float(point.count))
                if point.total is not None:
                    stats.setdefault('total', []).append(float(point.total))

    return {k: sum(v) / len(v) if v else None for k, v in stats.items()}

from datetime import datetime, timedelta, timezone
from azure.identity import DefaultAzureCredential
from azure.monitor.query import MetricsQueryClient, MetricAggregationType


def filter_metric_dimensions(payload, config=None):
    config = config or {}
    start = datetime.fromtimestamp(payload['start_time'], tz=timezone.utc)
    end = datetime.fromtimestamp(payload['end_time'], tz=timezone.utc)
    filter_str = payload.get('filter', None)

    with DefaultAzureCredential() as credential:
        with MetricsQueryClient(credential) as client:
            result = client.query_resource(config['resource_id'], metric_names=[payload['metric']],
                                           timespan=(start, end),
                                           granularity=timedelta(seconds=config.get('period_seconds', 60)),
                                           filter=filter_str,
                                           aggregations=[MetricAggregationType.AVERAGE])

    filtered_points = []
    for metric in result.metrics:
        for series in metric.timeseries:
            metadata = {dimension.name: dimension.value for dimension in series.metadata_values}
            for point in series.data:
                if point.average is not None:
                    filtered_points.append({
                        'timestamp': point.timestamp.timestamp(),
                        'value': float(point.average),
                        'dimensions': metadata
                    })
    return {'points': sorted(filtered_points, key=lambda point: point['timestamp'])}

from datetime import datetime, timedelta, timezone
from azure.identity import DefaultAzureCredential
from azure.monitor.query import MetricsQueryClient, MetricAggregationType


def compare_metric_series(payload, config=None):
    config = config or {}
    start = datetime.fromtimestamp(payload['start_time'], tz=timezone.utc)
    end = datetime.fromtimestamp(payload['end_time'], tz=timezone.utc)

    series_data = {}

    for i, filter_key in enumerate(['filter_a', 'filter_b']):
        filter_str = payload.get(filter_key)
        if not filter_str:
            continue

        with DefaultAzureCredential() as credential:
            with MetricsQueryClient(credential) as client:
                result = client.query_resource(config['resource_id'], metric_names=[payload['metric']],
                                               timespan=(start, end),
                                               granularity=timedelta(seconds=config.get('period_seconds', 60)),
                                               filter=filter_str,
                                               aggregations=[MetricAggregationType.AVERAGE])

        points = []
        for metric in result.metrics:
            for series in metric.timeseries:
                for point in series.data:
                    if point.average is not None:
                        points.append({'timestamp': point.timestamp.timestamp(), 'value': float(point.average)})
        series_data[filter_key] = sorted(points, key=lambda point: point['timestamp'])

    return series_data

from azure.identity import DefaultAzureCredential
from azure.monitor.query import MetricsQueryClient


class ObservabilityClient:
    def __init__(self, resource_id: str):
        self.resource_id = resource_id
        self.credential = DefaultAzureCredential()
        self.metrics_client = MetricsQueryClient(self.credential)

    def get_metrics_client(self):
        return self.metrics_client

    def get_resource_id(self):
        return self.resource_id

from typing import Dict, Any, List


class MetricPoint:
    def __init__(self, timestamp: float, value: float, dimensions: Dict[str, str] = None):
        self.timestamp = timestamp
        self.value = value
        self.dimensions = dimensions if dimensions is not None else {}

    def to_dict(self):
        return {
            "timestamp": self.timestamp,
            "value": self.value,
            "dimensions": self.dimensions
        }


class MetricSeries:
    def __init__(self, metric_name: str, points: List[MetricPoint], metadata: Dict[str, str] = None):
        self.metric_name = metric_name
        self.points = points
        self.metadata = metadata if metadata is not None else {}

    def to_dict(self):
        return {
            "metric_name": self.metric_name,
            "points": [p.to_dict() for p in self.points],
            "metadata": self.metadata
        }

import google.generativeai as genai
from google.generativeai.types import HarmCategory, HarmBlockThreshold
import os

def summarize_metric_trends(metric_data: dict, config: dict = None) -> dict:
    config = config or {}
    genai.configure(api_key=os.environ.get("GOOGLE_API_KEY"))
    model = genai.GenerativeModel('gemini-pro')

    prompt = (
        "Analyze the following metric data and summarize recent trends or anomalies. "
        "Provide a concise summary highlighting any significant changes, spikes, dips, or patterns.

"
        f"Metric Data: {metric_data}

Summary:"
    )

    response = model.generate_content(
        prompt,
        safety_settings={
            HarmCategory.HARM_CATEGORY_HATE_SPEECH: HarmBlockThreshold.BLOCK_NONE,
            HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT: HarmBlockThreshold.BLOCK_NONE,
            HarmCategory.HARM_CATEGORY_HARASSMENT: HarmBlockThreshold.BLOCK_NONE,
            HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT: HarmBlockThreshold.BLOCK_NONE,
        }
    )
    return {'summary': response.text}

import google.generativeai as genai
from google.generativeai.types import HarmCategory, HarmBlockThreshold
import os

def check_annotation_safety(annotation_text: str, config: dict = None) -> dict:
    config = config or {}
    genai.configure(api_key=os.environ.get("GOOGLE_API_KEY"))
    model = genai.GenerativeModel('gemini-pro')

    prompt = (
        "Analyze the following text for any unsafe content, including but not limited to "
        "hate speech, sexually explicit content, harassment, or dangerous content. "
        "Return 'safe' if no unsafe content is detected, otherwise return 'unsafe' "
        "and a brief reason.

"
        f"Text: {annotation_text}

Analysis:"
    )

    response = model.generate_content(
        prompt,
        safety_settings={
            HarmCategory.HARM_CATEGORY_HATE_SPEECH: HarmBlockThreshold.BLOCK_ONLY_HIGH,
            HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT: HarmBlockThreshold.BLOCK_ONLY_HIGH,
            HarmCategory.HARM_CATEGORY_HARASSMENT: HarmBlockThreshold.BLOCK_ONLY_HIGH,
            HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT: HarmBlockThreshold.BLOCK_ONLY_HIGH,
        }
    )
    # The response.text might contain a summary or a direct answer based on the prompt.
    # We will assume the model directly answers "safe" or "unsafe: [reason]"
    # A more robust solution might parse the safety_ratings from response.candidates[0].safety_ratings
    # and interpret them. For this example, we rely on the prompt to guide the text output.

    result_text = response.text.lower().strip()
    if result_text == 'safe':
        return {'status': 'safe'}
    else:
        return {'status': 'unsafe', 'reason': result_text.replace('unsafe:', '').strip()}

import os
from google.cloud import translate_v3 as translate


def translate_dashboard_note(note_text: str, target_language: str, config: dict = None) -> dict:
    config = config or {}
    client = translate.TranslationServiceClient()

    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT_ID")
    if not project_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT_ID environment variable not set.")

    location = "global"  # Or specific region like "us-central1"
    parent = f"projects/{project_id}/locations/{location}"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [note_text],
            "target_language_code": target_language,
        }
    )

    translated_text = ""
    for translation in response.translations:
        translated_text += translation.translated_text

    return {'translated_text': translated_text}
